-- This program creates the users table for AUTH-01 accounts. The table
-- is named users because user is a reserved word in PostgreSQL.
--
-- File:   V1__create_users_table.sql
-- Course: AUCSC 325
--

CREATE TABLE users (
    -- To identify each account; generated by the database
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- To store the unique login address
    email         VARCHAR(255) NOT NULL,
    -- To store the BCrypt hash, never the raw password
    password_hash VARCHAR(255) NOT NULL,
    -- To store CUSTOMER, SUPPLIER, or ADMIN
    role          VARCHAR(20)  NOT NULL,
    -- To reject a second account with the same email
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_role CHECK (role IN ('CUSTOMER', 'SUPPLIER', 'ADMIN'))
);
